//! B4 oracle tests: mathd's differentiator against two independent oracles
//! (work order B4, `docs/work-orders.md`, "B4 · Differentiator").
//!
//! 1. External Library Oracle: SymPy 1.14.0 + mpmath 1.3.0 computed at 35 digits
//!    of working precision (`mathd/fixtures/diff.json`, generated by
//!    `mathd/fixtures/generate.py`). Cross-checks derivatives of B3 fixture
//!    cases extended with systematic rule-by-rule cases.
//! 2. Algorithmic Oracle: Central finite differences (h = 1e-5) across at least
//!    10,000 generated expressions evaluated at 5 points each (50,000 evaluations).
//!    Independent algorithm and execution path. Skips undefined points and large
//!    second derivatives (|f''(x)| > 1e4), and asserts the skip count is bounded.

use mathd::{differentiate, eval_at, parse, BinOp, Const, Expr, Function, UnaryOp};
use std::collections::HashMap;
use std::fs;

// ---------------------------------------------------------------- JSON reader

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(pairs) => pairs.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    fn as_str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }
    fn as_f64(&self) -> Option<f64> {
        match self {
            Json::Num(v) => Some(*v),
            _ => None,
        }
    }
    fn as_arr(&self) -> Option<&[Json]> {
        match self {
            Json::Arr(v) => Some(v),
            _ => None,
        }
    }
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() && (self.b[self.i] as char).is_ascii_whitespace() {
            self.i += 1;
        }
    }
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn expect(&mut self, c: u8) -> Result<(), String> {
        if self.peek() == Some(c) {
            self.i += 1;
            Ok(())
        } else {
            Err(format!(
                "expected '{}' at byte {}, found {:?}",
                c as char,
                self.i,
                self.peek().map(|x| x as char)
            ))
        }
    }
    fn value(&mut self) -> Result<Json, String> {
        self.ws();
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') => self.string().map(Json::Str),
            Some(b't') => self.lit("true").map(|_| Json::Bool(true)),
            Some(b'f') => self.lit("false").map(|_| Json::Bool(false)),
            Some(b'n') => self.lit("null").map(|_| Json::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.number(),
            other => Err(format!(
                "unexpected {:?} at byte {}",
                other.map(|x| x as char),
                self.i
            )),
        }
    }
    fn lit(&mut self, s: &str) -> Result<(), String> {
        if self.b[self.i..].starts_with(s.as_bytes()) {
            self.i += s.len();
            Ok(())
        } else {
            Err(format!("expected literal '{}' at byte {}", s, self.i))
        }
    }
    fn string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let mut out = String::new();
        while self.i < self.b.len() {
            let c = self.b[self.i];
            self.i += 1;
            match c {
                b'"' => return Ok(out),
                b'\\' => {
                    let esc = self
                        .b
                        .get(self.i)
                        .copied()
                        .ok_or_else(|| "dangling escape".to_string())?;
                    self.i += 1;
                    match esc {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\x08'),
                        b'f' => out.push('\x0c'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            if self.i + 4 > self.b.len() {
                                return Err("truncated \\u escape".to_string());
                            }
                            let hex = std::str::from_utf8(&self.b[self.i..self.i + 4])
                                .map_err(|e| e.to_string())?;
                            self.i += 4;
                            let codepoint =
                                u32::from_str_radix(hex, 16).map_err(|e| e.to_string())?;
                            let ch = char::from_u32(codepoint)
                                .ok_or_else(|| format!("invalid codepoint {:x}", codepoint))?;
                            out.push(ch);
                        }
                        other => return Err(format!("unknown escape \\{}", other as char)),
                    }
                }
                _ => out.push(c as char),
            }
        }
        Err("unterminated string".to_string())
    }
    fn number(&mut self) -> Result<Json, String> {
        let start = self.i;
        if self.peek() == Some(b'-') {
            self.i += 1;
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.i += 1;
            } else {
                break;
            }
        }
        if self.peek() == Some(b'.') {
            self.i += 1;
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    self.i += 1;
                } else {
                    break;
                }
            }
        }
        if let Some(c) = self.peek() {
            if c == b'e' || c == b'E' {
                self.i += 1;
                if self.peek() == Some(b'+') || self.peek() == Some(b'-') {
                    self.i += 1;
                }
                while let Some(d) = self.peek() {
                    if d.is_ascii_digit() {
                        self.i += 1;
                    } else {
                        break;
                    }
                }
            }
        }
        let s = std::str::from_utf8(&self.b[start..self.i]).map_err(|e| e.to_string())?;
        let v: f64 = s
            .parse()
            .map_err(|e: std::num::ParseFloatError| e.to_string())?;
        Ok(Json::Num(v))
    }
    fn array(&mut self) -> Result<Json, String> {
        self.expect(b'[')?;
        let mut v = Vec::new();
        self.ws();
        if self.peek() == Some(b']') {
            self.i += 1;
            return Ok(Json::Arr(v));
        }
        loop {
            v.push(self.value()?);
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b']') => {
                    self.i += 1;
                    return Ok(Json::Arr(v));
                }
                other => return Err(format!("expected ',' or ']' in array, got {:?}", other)),
            }
        }
    }
    fn object(&mut self) -> Result<Json, String> {
        self.expect(b'{')?;
        let mut pairs = Vec::new();
        self.ws();
        if self.peek() == Some(b'}') {
            self.i += 1;
            return Ok(Json::Obj(pairs));
        }
        loop {
            self.ws();
            let k = self.string()?;
            self.ws();
            self.expect(b':')?;
            let val = self.value()?;
            pairs.push((k, val));
            self.ws();
            match self.peek() {
                Some(b',') => {
                    self.i += 1;
                }
                Some(b'}') => {
                    self.i += 1;
                    return Ok(Json::Obj(pairs));
                }
                other => return Err(format!("expected ',' or '}}' in object, got {:?}", other)),
            }
        }
    }
}

fn parse_json(s: &str) -> Result<Json, String> {
    let mut p = P {
        b: s.as_bytes(),
        i: 0,
    };
    let val = p.value()?;
    p.ws();
    if p.i != p.b.len() {
        return Err(format!("trailing characters at byte {}", p.i));
    }
    Ok(val)
}

struct DiffCase {
    expr: String,
    var: String,
    bindings: HashMap<String, f64>,
    expected: f64,
}

fn load_diff_cases() -> Vec<DiffCase> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/diff.json");
    let text =
        fs::read_to_string(path).unwrap_or_else(|e| panic!("failed to read {}: {}", path, e));
    let root = parse_json(&text).unwrap_or_else(|e| panic!("failed to parse {}: {}", path, e));
    let cases = root
        .get("cases")
        .and_then(|v| v.as_arr())
        .expect("diff.json missing cases array");

    cases
        .iter()
        .map(|c| {
            let expr = c.get("expr").and_then(|v| v.as_str()).unwrap().to_string();
            let var = c.get("var").and_then(|v| v.as_str()).unwrap().to_string();
            let expected = c.get("expected").and_then(|v| v.as_f64()).unwrap();
            let mut bindings = HashMap::new();
            if let Some(Json::Obj(pairs)) = c.get("bindings") {
                for (k, v) in pairs {
                    if let Some(num) = v.as_f64() {
                        bindings.insert(k.clone(), num);
                    }
                }
            }
            DiffCase {
                expr,
                var,
                bindings,
                expected,
            }
        })
        .collect()
}

// ---------------------------------------------------------------- Oracle 1: SymPy fixtures

#[test]
fn sympy_fixtures_agree() {
    let cases = load_diff_cases();
    assert!(
        cases.len() >= 700,
        "diff.json must contain at least 700 cases, found {}",
        cases.len()
    );

    let mut failures = Vec::new();
    let mut checked = 0;

    for c in &cases {
        let ast = match parse(&c.expr) {
            Ok(a) => a,
            Err(e) => {
                failures.push(format!("PARSE FAIL {:?}: {:?}", c.expr, e));
                continue;
            }
        };

        let deriv = differentiate(&ast, &c.var);
        match eval_at(&deriv, &c.bindings) {
            Ok(actual) => {
                checked += 1;
                let diff = (actual - c.expected).abs();
                let scale = c.expected.abs().max(1.0);
                let tol = 1e-10;
                if diff > tol * scale {
                    failures.push(format!(
                        "VALUE d/d{}({:?}) at {:?}: got {}, expected {}, diff {}, tol {}",
                        c.var,
                        c.expr,
                        c.bindings,
                        actual,
                        c.expected,
                        diff,
                        tol * scale
                    ));
                }
            }
            Err(e) => {
                failures.push(format!(
                    "EVAL FAIL d/d{}({:?}) at {:?}: {:?}",
                    c.var, c.expr, c.bindings, e
                ));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "{} of {} SymPy derivative fixture cases failed:\n{}",
        failures.len(),
        checked,
        failures.join("\n")
    );
}

#[test]
fn fixture_header_counts_match_data() {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/diff.json");
    let text = fs::read_to_string(path).unwrap();
    let root = parse_json(&text).unwrap();
    let claimed_total = root
        .get("total_cases")
        .and_then(|v| v.as_f64())
        .expect("total_cases missing") as usize;
    let cases = root
        .get("cases")
        .and_then(|v| v.as_arr())
        .expect("cases array missing");
    assert_eq!(
        claimed_total,
        cases.len(),
        "header claimed {} total cases, actual array has {}",
        claimed_total,
        cases.len()
    );
}

// ---------------------------------------------------------------- Oracle 2: CFD property test

struct Rng(u64);

impl Rng {
    fn next_u64(&mut self) -> u64 {
        // xorshift64*
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }
}

fn gen_leaf(rng: &mut Rng) -> Expr {
    match rng.below(4) {
        0 => Expr::Integer(rng.below(6) as i64 + 1),
        1 => Expr::Decimal((rng.below(16) as f64 + 1.0) / 4.0),
        2 => Expr::Constant(if rng.below(2) == 0 {
            Const::Pi
        } else {
            Const::E
        }),
        _ => {
            if rng.below(3) == 0 {
                Expr::Variable("y".to_string())
            } else {
                Expr::Variable("x".to_string())
            }
        }
    }
}

fn gen_cfd_expr(rng: &mut Rng, depth: u32) -> Expr {
    if depth == 0 || rng.below(100) < 30 {
        return gen_leaf(rng);
    }
    let r = rng.below(100);
    if r < 45 {
        let op = match rng.below(4) {
            0 => BinOp::Add,
            1 => BinOp::Sub,
            2 => BinOp::Mul,
            _ => BinOp::Div,
        };
        Expr::BinOp {
            op,
            left: Box::new(gen_cfd_expr(rng, depth - 1)),
            right: Box::new(gen_cfd_expr(rng, depth - 1)),
        }
    } else if r < 60 {
        // Bounded integer powers to avoid explosive values
        Expr::BinOp {
            op: BinOp::Pow,
            left: Box::new(gen_cfd_expr(rng, depth - 1)),
            right: Box::new(Expr::Integer(rng.below(3) as i64 + 1)),
        }
    } else if r < 85 {
        let funcs = [
            Function::Sin,
            Function::Cos,
            Function::Tan,
            Function::Exp,
            Function::Ln,
            Function::Sqrt,
            Function::Abs,
        ];
        let func = funcs[rng.below(funcs.len() as u64) as usize];
        Expr::Call {
            func,
            args: vec![gen_cfd_expr(rng, depth - 1)],
        }
    } else {
        Expr::UnaryOp {
            op: UnaryOp::Neg,
            operand: Box::new(gen_cfd_expr(rng, depth - 1)),
        }
    }
}

#[test]
fn central_finite_differences_property_test() {
    const SEEDS: [u64; 4] = [
        0xB401_0000_0001,
        0xB401_0000_0002,
        0xB401_0000_0003,
        0xB401_0000_0004,
    ];
    const EXPRS_PER_SEED: usize = 2_500;
    const POINTS_PER_EXPR: usize = 5;
    const TOTAL_TARGET_EXPRS: usize = SEEDS.len() * EXPRS_PER_SEED; // 10,000 expressions

    let h = 1e-5;
    let mut tested_expressions = 0;
    let mut tested_points = 0;
    let mut skip_count = 0;
    let mut failures = Vec::new();

    for &seed in &SEEDS {
        let mut rng = Rng(seed);
        for _ in 0..EXPRS_PER_SEED {
            let expr = gen_cfd_expr(&mut rng, 3);
            let d_expr = differentiate(&expr, "x");
            tested_expressions += 1;

            for _ in 0..POINTS_PER_EXPR {
                // Generate evaluation point in [-3.0, 3.0], away from exact 0 to avoid corner singularities
                let raw_u = (rng.below(6000) as f64) / 1000.0 - 3.0;
                let x = if raw_u.abs() < 0.05 {
                    if raw_u >= 0.0 {
                        0.05
                    } else {
                        -0.05
                    }
                } else {
                    raw_u
                };

                let mut b_center = HashMap::new();
                b_center.insert("x".to_string(), x);
                b_center.insert("y".to_string(), 1.5);

                let mut b_plus = HashMap::new();
                b_plus.insert("x".to_string(), x + h);
                b_plus.insert("y".to_string(), 1.5);

                let mut b_minus = HashMap::new();
                b_minus.insert("x".to_string(), x - h);
                b_minus.insert("y".to_string(), 1.5);

                let f_center = eval_at(&expr, &b_center);
                let f_plus = eval_at(&expr, &b_plus);
                let f_minus = eval_at(&expr, &b_minus);

                // Skip if f is undefined at any of the evaluation points
                let (fc, fp, fm) = match (f_center, f_plus, f_minus) {
                    (Ok(c), Ok(p), Ok(m)) => (c, p, m),
                    _ => {
                        skip_count += 1;
                        continue;
                    }
                };

                // Skip points where function magnitude exceeds f64 CFD precision limit (catastrophic cancellation)
                if fc.abs() > 1e6 || fp.abs() > 1e6 || fm.abs() > 1e6 {
                    skip_count += 1;
                    continue;
                }

                // Second derivative check: |f''(x)| ≈ |f(x+h) - 2f(x) + f(x-h)| / h^2
                let f_pp = (fp - 2.0 * fc + fm) / (h * h);
                if !f_pp.is_finite() || f_pp.abs() > 1e4 {
                    // Skip points where second derivative is very large (> 1e4)
                    skip_count += 1;
                    continue;
                }

                // Central finite differences formula: (f(x+h) - f(x-h)) / (2h)
                let cfd = (fp - fm) / (2.0 * h);

                // Symbolic derivative evaluation
                let d_val = match eval_at(&d_expr, &b_center) {
                    Ok(v) => v,
                    Err(_) => {
                        skip_count += 1;
                        continue;
                    }
                };

                tested_points += 1;

                // Tolerance accounting for O(h^2) truncation error and floating point cancellation
                let tol = 1e-5 * d_val.abs().max(1.0) + 1e-4;
                let diff = (d_val - cfd).abs();

                if diff > tol {
                    failures.push(format!(
                        "CFD MISMATCH at x={}: d_val={}, cfd={}, diff={}, tol={}",
                        x, d_val, cfd, diff, tol
                    ));
                    if failures.len() >= 10 {
                        break;
                    }
                }
            }
            if failures.len() >= 10 {
                break;
            }
        }
    }

    assert_eq!(
        tested_expressions, TOTAL_TARGET_EXPRS,
        "expected {} expressions, tested {}",
        TOTAL_TARGET_EXPRS, tested_expressions
    );

    let total_evaluations = tested_expressions * POINTS_PER_EXPR;
    let skip_rate = (skip_count as f64) / (total_evaluations as f64) * 100.0;

    // Report skip count explicitly as required by work order
    println!(
        "CFD property test: tested {} points across {} expressions (skipped {} of {} points, skip rate {:.2}%)",
        tested_points, tested_expressions, skip_count, total_evaluations, skip_rate
    );

    assert!(
        failures.is_empty(),
        "Central finite differences failures:\n{}",
        failures.join("\n")
    );

    // Verify skip rate does not hide defects
    assert!(
        skip_count < total_evaluations / 2,
        "skip count too high: {} of {} ({:.2}%)",
        skip_count,
        total_evaluations,
        skip_rate
    );
    assert!(
        tested_points >= 25_000,
        "tested points must be >= 25,000, got {}",
        tested_points
    );
}

// ---------------------------------------------------------------- Break / Sabotage test

#[test]
fn sabotage_sign_flip_detected() {
    // AGENTS.md rule: tests must be capable of failing loudly when the code is broken.
    let expr = parse("sin(x) + x^3").unwrap();
    let d = differentiate(&expr, "x");
    let mut bindings = HashMap::new();
    bindings.insert("x".to_string(), 1.5);

    let h = 1e-5;
    let mut b_plus = HashMap::new();
    b_plus.insert("x".to_string(), 1.5 + h);
    let mut b_minus = HashMap::new();
    b_minus.insert("x".to_string(), 1.5 - h);

    let cfd = (eval_at(&expr, &b_plus).unwrap() - eval_at(&expr, &b_minus).unwrap()) / (2.0 * h);
    let correct_d = eval_at(&d, &bindings).unwrap();

    // Correct derivative matches CFD
    assert!((correct_d - cfd).abs() < 1e-5);

    // Sabotaged sign: -d fails CFD check
    let sabotaged_d = -correct_d;
    assert!(
        (sabotaged_d - cfd).abs() > 1.0,
        "sabotaged sign flip must be detected by CFD oracle"
    );
}
